import pathlib,os,time,json,re
root=pathlib.Path('/home/appontrack')
candidates=[root/'public_html/error_log',root/'public_html/device/v1/error_log',root/'public_html/saas/console/error_log',root/'logs/php_error.log',root/'logs/error_log',root/'logs/php-fpm.log',root/'public_html/.user.ini']
logpaths=[]
for p in candidates:
 if p.is_file() and not p.is_symlink():logpaths.append(p)
for base in [root/'logs',root/'public_html']:
 if base.is_dir():
  try:
   for p in base.iterdir():
    if p.is_file() and ('error' in p.name.lower() or 'php' in p.name.lower()) and p not in logpaths:
     logpaths.append(p)
  except:pass
report=[]
for p in logpaths[:15]:
 try:
  stat=p.stat()
  size=stat.st_size
  with p.open('rb') as file:
   file.seek(max(0,size-125000));a=file.read().decode('utf-8','replace').splitlines()
  match=[s for s in a if ('Fatal error' in s or 'Uncaught ' in s or 'SQLSTATE' in s or 'PHP Warning' in s or 'device/v1' in s or 'TenantWorkspace' in s or 'HumanEscalations' in s)]
  tail=[re.sub(r'(?i)(authorization|bearer|api[-_]?key|token|password)([\\s\\x22:=]+)[^\\s,;]+',r'\\1\\2[redacted]',v)[:380] for v in match[-19:]]
  report.append({'path':str(p),'modified':round(time.time()-stat.st_mtime),'bytes':size,'errors':tail})
 except Exception as e:report.append({'path':str(p),'error':type(e).__name__})
print(json.dumps({'checks':report},ensure_ascii=False))
